import {questions,lessons} from './data.js';
import {answer,gradeNumeric} from './core.js';
import {updateReview} from './review.js';
import {retryTexts} from './card-variants.js';
import {transferProblems} from './card-math.js';
import {generateProblem,mathFamilies} from './math-reference.js';
import {recordEvent,gradeShort,prerequisite,advancedReady,topicMastered,markDiagnostic} from './adaptive.js';
export const questionById=new Map(questions.map(q=>[q.id,q]));
export const difficulty=q=>q.level||(q.kind==='calculation'?3:q.kind==='scenario'?2:1);
export function shuffle(a,rng=Math.random){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
export const dueQuestions=(s,ch=-1,now=Date.now())=>questions.filter(q=>(ch<0||q.ch===ch)&&((s.memory?.[q.id]?.due??s.records[q.id]?.due)??Infinity)<=now);
export const weakQuestions=(s,ch=-1)=>questions.filter(q=>{if(ch>=0&&q.ch!==ch)return false;let last=s.profile?.events.filter(e=>e.qid===q.id&&e.independent).at(-1);return last? !last.ok:s.memory?.[q.id]?s.memory[q.id].lastGrade<2:s.records[q.id]&&!s.records[q.id].lastOK});
function card(q,format='mcq',stage=null,variant=0,rng=Math.random){return {qid:q.id,ch:q.ch,format,stage,variant,order:shuffle([0,1,2,3],rng),status:'unanswered',choice:null,quality:null,deep:false,draft:'',support:0}}
function tokens(s){s.serial=Number.isInteger(s.serial)?s.serial:0;for(let c of s.cards)if(!c.token)c.token='c'+(++s.serial);return s}
function interleave(pool){let queues=[0,1,2,3].map(ch=>pool.filter(q=>q.ch===ch)),out=[];while(queues.some(q=>q.length))for(let queue of queues)if(queue.length)out.push(queue.shift());return out}
export function newSession(state,{chapter=-1,mode='learn',size=10,family=null,now=Date.now(),rng=Math.random}={}){
 let pool=mode==='due'?dueQuestions(state,chapter,now):mode==='wrong'?weakQuestions(state,chapter):questions.filter(q=>(chapter<0||q.ch===chapter)&&(mode!=='math'||q.worked));if(!pool.length)return null;
 let cards=[];const seen=q=>state.memory?.[q.id]||state.records[q.id];
 if(mode==='diagnostic'){pool=[0,1,2,3].filter(ch=>chapter<0||chapter===ch).flatMap(ch=>[questions.find(q=>q.ch===ch&&q.level===1),questions.find(q=>q.ch===ch&&q.level===2)]);cards=pool.map(q=>card(q,'mcq',null,0,rng))}
 else if(mode==='math'&&family){let f=mathFamilies.find(f=>f.id===family&&(chapter<0||f.ch===chapter));if(!f)return null;let q=questionById.get(f.qid);for(let i=0;i<2;i++){let generated={family,seed:(now+i*997)>>>0};for(let step=0;step<4;step++)cards.push({...card(q,'math',step,0,rng),generated});cards.push({...card(q,'transfer',null,0,rng),generated})}}
 else {
  let priority=q=>advancedReady(state,q.topicId)&&q.level===1?99:!seen(q)?difficulty(q):10+difficulty(q);
  let fresh=[1,2,3,4,11,12,13,14,99].flatMap(level=>{let p=pool.filter(q=>priority(q)===level);return chapter<0?interleave(p):p});let due=dueQuestions(state,chapter,now).filter(q=>pool.includes(q)).sort((a,b)=>(state.memory?.[a.id]?.due??state.records[a.id]?.due)-(state.memory?.[b.id]?.due??state.records[b.id]?.due));
  if(mode==='learn'){let used=new Set(),woven=[];while(woven.length<pool.length){let q=(woven.length%3===2?due:fresh).find(q=>!used.has(q.id))||fresh.find(q=>!used.has(q.id))||due.find(q=>!used.has(q.id));if(!q)break;used.add(q.id);woven.push(q)}pool=woven}else if(mode==='due'||mode==='wrong')pool.sort((a,b)=>(state.memory?.[a.id]?.due??state.records[a.id]?.due??0)-(state.memory?.[b.id]?.due??state.records[b.id]?.due??0));else pool=fresh;
  for(let q of pool){if(cards.length>=size)break;let math=q.worked&&(!seen(q)||mode==='math')&&!advancedReady(state,q.topicId);if(math){if(size-cards.length<5)continue;for(let step=0;step<4;step++)cards.push(card(q,'math',step,0,rng));cards.push(card(q,'transfer',null,0,rng))}else {let r=state.profile?.topics?.[q.topicId],format=q.worked&&advancedReady(state,q.topicId)?'transfer':q.shortEligible&&((seen(q)&&!r?.unprompted&&cards.length%2===1)||cards.length%5===3)?'short':cards.length%4===2?'recall':'mcq';cards.push(card(q,format,null,0,rng))}}
  if(mode==='learn')for(let q of questions.filter(q=>q.kind!=='calculation'&&(chapter<0||q.ch===chapter)&&!cards.some(c=>c.qid===q.id))){if(cards.length>=size)break;cards.push(card(q,q.shortEligible?'short':'recall',null,0,rng))}
 }
 if(!cards.length)return null;return tokens({version:1,id:'s'+now+'-'+Math.floor(rng()*1e9),chapter,mode,baseCount:cards.length,cards,index:0,finished:false,started:now,retried:[],updated:now,serial:0});
}
const stageReasons=[['Dữ kiện đúng theo đề.','Byte đổi sang bit bằng nhân 8, không chia 8.','Total length gồm header; payload phải trừ header nếu đề cho tổng gói.','Sequence number là chỉ số byte, không phải lượng dữ liệu đã nhận.'],['Đổi đơn vị đúng.','Phải đổi byte sang bit khi tốc độ theo bit/s.','Mbps dùng hệ số 10⁶ trong đề; không đổi bằng bội 1024.','Từ ms sang s phải chia 1000.'],['Công thức đúng.','R/L có đơn vị 1/s, không phải thời gian truyền.','Link chậm nhất giới hạn thông lượng tuyến nối tiếp.','ACK chỉ byte tiếp theo đang chờ; không phải byte cuối đã nhận.']];
const stageNames=['Nhận diện dữ liệu & ký hiệu','Đổi đơn vị','Chọn công thức','Thay số & kết quả'];
function generatedFor(c,extra=0){return c.generated?generateProblem(c.generated.family,(c.generated.seed+extra)>>>0):null}
export function getCardView(c){let original=questionById.get(c.qid);if(!original)throw Error('Không tìm thấy thẻ.');let g=generatedFor(c),q=g?{...original,text:g.prompt,options:g.options,correct:g.correct,worked:g.worked,pages:g.pages,distractorReasons:g.reasons,explain:g.worked.substitution+'. '+g.worked.result,sourceKind:'generated',sourceLabel:'Biến thể tự sinh đã kiểm tra bằng hàm tham chiếu'}:original,l=lessons.find(l=>l.id===q.lesson),prompt=c.variant?retryTexts[q.id]:q.text,options=q.options,correct=q.correct,worked=q.worked,answerText=options[correct],stageLabel='',reasons=q.distractorReasons;
 if(c.format==='short'){prompt=q.shortPrompt||prompt;answerText=q.shortAnswers[0]}
 if(c.format==='math'){stageLabel=stageNames[c.stage];if(c.stage<3){let field=['given','conversion','formula'][c.stage];prompt=['Dữ kiện và ý nghĩa ký hiệu nào đúng với đề này?','Cách đổi đơn vị/hệ đếm nào đúng để giải đề này?','Công thức hoặc quy tắc nào giải đúng mục tiêu của đề?'][c.stage];let right=c.stage===0?worked.given+' '+worked.symbols:worked[field];let bad=c.stage===1?['Giữ nguyên số byte khi dùng tốc độ theo bit/s.','Đổi Mbps thành bit/s bằng hệ số 1024.','Đổi ms sang s bằng cách nhân 1000.']:c.stage===0?['Đổi mọi kích thước byte thành bit bằng cách chia 8.','Coi độ dài toàn bộ gói đã gồm header là payload riêng.','Coi số thứ tự byte và số lượng byte đã nhận là cùng một đại lượng.']:['Lấy tốc độ chia độ dài để được thời gian truyền.','Dùng tốc độ link nhanh nhất làm thông lượng của tuyến nối tiếp.','Lấy byte cuối đã nhận làm ACK thay byte mong đợi tiếp theo.'];options=[right,...bad];correct=0;answerText=right;reasons=stageReasons[c.stage]}}
 if(c.format==='transfer'){let p=generatedFor(c,9973)||transferProblems[q.objective]||transferProblems[q.id]||(q.mathFamily?generateProblem(q.mathFamily,Number(c.seed||37)):null);if(!p)throw Error('Thiếu bài tương tự.');return {q,l,p,prompt:p.prompt,stageLabel:'Tự làm bài tương tự',answerText:p.answer+' '+p.unit,worked:p.worked,rows:p.rows||null,assumptions:p.assumptions||'Dùng giả thiết đã ghi rõ trong đề.'}}
 return {q,l,prompt,reasons,context:c.format==='math'?q.text:null,options,correct,answerText,worked,stageLabel,rows:g?.rows||null,assumptions:g?.assumptions||null};
}
function scheduleRetry(session,c){if(c.variant||c.filler||session.retried.includes(c.qid)||session.mode==='diagnostic')return;session.retried.push(c.qid);let lastBlock=c.format==='math'?session.cards.reduce((last,x,i)=>x.qid===c.qid?Math.max(last,i):last,session.index):session.index;let at=Math.max(session.index+3,lastBlock+3);while(at<session.cards.length&&at>0&&session.cards[at].qid===session.cards[at-1].qid&&['math','transfer'].includes(session.cards[at].format))at++;while(session.cards.length<at){let q=questions.find(q=>q.kind==='theory'&&q.id!==c.qid&&!session.cards.some(x=>x.qid===q.id)&&(session.chapter<0||q.ch===session.chapter))||questions.find(q=>q.kind==='theory'&&q.id!==c.qid&&q.id!==session.cards.at(-1)?.qid&&(session.chapter<0||q.ch===session.chapter));session.cards.push({...card(q,'recall'),filler:true})}session.cards.splice(Math.min(at,session.cards.length),0,card(questionById.get(c.qid),'mcq',null,1));tokens(session)}
export function flipCard(session){let c=session?.cards[session.index];if(c?.format==='recall'&&c.status==='unanswered'){c.status='flipped';return true}return false}
export function respond(state,session,value,now=Date.now()){
 if(!session||session.finished)return {changed:false};tokens(session);let c=session.cards[session.index];if(c.status==='answered')return {changed:false};let v=getCardView(c),quality,choice=null,previous=state.memory?.[c.qid]?.lastGrade;
 if(c.format==='recall'){if(c.status!=='flipped'||![0,1,3].includes(value))return {changed:false};quality=value}
 else if(c.format==='short'){if(value===null)quality=0;else{let result=gradeShort(value,v.q);if(!result.valid)return {changed:false,error:'Nhập câu trả lời ngắn hoặc chọn Chưa biết.'};quality=result.ok?2:0;choice=String(value)}}
 else if(c.format==='transfer'){if(value===null)quality=0;else{let result=gradeNumeric(value,v.p.answer,v.p.grading);if(!result.valid)return {changed:false,error:'Nhập một số hữu hạn, không kèm đơn vị.'};quality=result.ok?2:0;choice=result.value}}
 else {if(!Number.isInteger(value)||value< -1||value>3)return {changed:false};choice=value;quality=value===-1?0:c.order[value]===v.correct?2:0}
 Object.assign(c,{status:'answered',quality,choice,answeredAt:now});session.updated=now;const checkpoint=c.format==='math'&&c.stage<3;
 if(!checkpoint||quality===0){answer(state,c.qid,quality>=2,now);updateReview(state,c.qid,quality,c.format,now)}
 recordEvent(state,v.q,{id:session.id+':'+c.token,runId:session.id,quality,format:c.format,support:c.format==='math'?Math.max(1,c.support||0):c.support||0,checkpoint,novel:c.format==='transfer'||v.q.level>=3,now,elapsed:now-(c.openedAt||session.started),viewedSolution:!!c.solutionBefore});
 if(quality===0){scheduleRetry(session,c);if(previous===0&&!c.filler&&session.mode!=='diagnostic'){let base=prerequisite(v.q,questions);c.help=true;c.supportReason='Sai liên tiếp: cần củng cố kiến thức nền '+base.options[base.correct]+'.';if(base.id!==c.qid&&!session.cards.slice(session.index+1,session.index+3).some(x=>x.qid===base.id)){session.cards.splice(session.index+1,0,{...card(base),support:1,filler:true,help:true});tokens(session)}}}
 return {changed:true,quality};
}
export function nextCard(session){if(!session||session.finished||session.cards[session.index].status!=='answered')return false;if(session.index+1<session.cards.length)session.index++;else session.finished=true;return true}
export function intervene(state,session,action){if(!session||session.finished)return false;let c=session.cards[session.index],q=questionById.get(c.qid);if(c.status==='answered')return false;if(action==='explain'){c.support=(c.support||0)+1;c.help=true;return true}if(action==='easier'){let base=prerequisite(q,questions);c.support=(c.support||0)+1;c.help=true;if(base.id!==q.id){session.cards.splice(session.index+3,0,c);session.cards[session.index]={...card(base),support:1,help:true,filler:true};tokens(session)}return true}if(action==='harder'){let candidates=questions.filter(x=>x.ch===q.ch&&x.id!==q.id&&x.level>q.level),next=candidates.find(x=>x.cluster===q.cluster)||candidates[0];if(!next){c.help=true;c.supportReason='Bạn đang ở mức cao nhất của bộ câu hỏi này.';return true}session.cards[session.index]=card(next,next.worked?'transfer':next.shortEligible?'short':'mcq');tokens(session);return true}return false}
export function finishSession(state,session,now=Date.now()){markDiagnostic(state,session,now)}
export function cleanSession(raw){if(!raw||raw.version!==1||!Array.isArray(raw.cards)||!raw.cards.length||raw.cards.length>200||!Number.isInteger(raw.index)||raw.index<0||raw.index>=raw.cards.length||![-1,0,1,2,3].includes(raw.chapter))return null;let cards=[],used=new Set();for(let c of raw.cards){if(!questionById.has(c.qid)||!['mcq','recall','math','transfer','short'].includes(c.format)||!['unanswered','flipped','answered'].includes(c.status)||!Array.isArray(c.order)||c.order.length!==4||[...c.order].sort().join('')!=='0123')return null;let q=questionById.get(c.qid);if(['math','transfer'].includes(c.format)&&!q.worked)return null;if(c.format==='math'&&(!Number.isInteger(c.stage)||c.stage<0||c.stage>3))return null;if(c.status==='answered'&&![0,1,2,3].includes(c.quality))return null;let generated=null;if(c.generated){if(!mathFamilies.some(f=>f.id===c.generated.family&&f.qid===c.qid)||!Number.isInteger(c.generated.seed)||c.generated.seed<0||c.generated.seed>4294967295)return null;generated={family:c.generated.family,seed:c.generated.seed}}let token=typeof c.token==='string'&&c.token.length<50&&!used.has(c.token)?c.token:null;if(token)used.add(token);cards.push({qid:c.qid,ch:q.ch,token,format:c.format,stage:c.stage,variant:c.variant===1?1:0,filler:c.filler===true,order:[...c.order],status:c.status,choice:typeof c.choice==='number'||typeof c.choice==='string'?c.choice:null,quality:c.quality,deep:c.deep===true,draft:typeof c.draft==='string'?c.draft.slice(0,1000):'',support:Number.isInteger(c.support)?Math.max(0,Math.min(c.support,100)):0,help:!!c.help,supportReason:typeof c.supportReason==='string'?c.supportReason.slice(0,300):'',solutionBefore:!!c.solutionBefore,scaffolded:!!c.scaffolded,...(generated?{generated}:{})})}return tokens({version:1,id:typeof raw.id==='string'&&raw.id.length<100?raw.id:'legacy-'+Number(raw.started||0),chapter:raw.chapter,mode:['learn','due','wrong','math','diagnostic'].includes(raw.mode)?raw.mode:'learn',baseCount:Math.min(10,Number(raw.baseCount)||10),cards,index:raw.index,finished:raw.finished===true,started:Number(raw.started)||Date.now(),updated:Number(raw.updated)||Date.now(),serial:Number(raw.serial)||cards.length,retried:Array.isArray(raw.retried)?raw.retried.filter(id=>questionById.has(id)):[]})}
export const masteredCount=s=>Object.values(s.profile?.topics||{}).filter(topicMastered).length;
